  // the faces of that tile lie at plus or minus half of the pitch along each
  // axis. Compute the distance to the oncoming face along every axis the
  // particle is moving along and retain the smallest of those distances.
  double d {INFTY};
  array<int, 3> lattice_trans {0, 0, 0};

  int n_axes = is_3d_ ? 3 : 2;
  for (int i = 0; i < n_axes; ++i) {
    if (u[i] == 0.0)
      continue;

    // Coordinate of the tile face that the particle is heading towards
    double face {std::copysign(0.5 * pitch_[i], u[i])};

    // Skip this axis if the particle already lies on its oncoming face. Such a
    // crossing has already been handled, and accounting for it again would
    // yield a zero distance that leaves the particle stuck on the face.
    if (std::abs(r[i] - face) <= surface_tolerance(i))
      continue;

    // The tile index changes along the axis giving the shortest distance. It is
    // determined here from that axis directly: recovering it afterwards by
    // testing whether the advanced position coincides with a face would
    // require comparing lengths against an absolute tolerance, which cannot
    // hold for arbitrarily large lattices and would silently report a crossing
    // with no change of tile.
    double d_axis {(face - r[i]) / u[i]};
    if (d_axis < d) {
      d = d_axis;
      lattice_trans = {0, 0, 0};
      lattice_trans[i] = (u[i] > 0.0) ? 1 : -1;
    }
  }

  return {d, lattice_trans};
}

