using namespace openmc;

namespace {

//! Build a rectangular lattice of void universes from its parameters
std::unique_ptr<RectLattice> make_lattice(
  const std::string& dimension, double lower_left, double pitch, int n_universe)
{
  std::string universes;
  for (int i = 0; i < n_universe; ++i) {
    universes += " 1";
  }
  std::string ll = std::to_string(lower_left);
  std::string p = std::to_string(pitch);
  std::string xml = "<lattice id=\"1\"><dimension>" + dimension +
                    "</dimension><lower_left>" + ll + " " + ll;
  std::string pitch_str = p + " " + p;
  if (dimension.size() > 3) { // three entries, e.g. "3 3 3"
    ll += " " + std::to_string(lower_left);
    pitch_str += " " + p;
    xml = "<lattice id=\"1\"><dimension>" + dimension +
          "</dimension><lower_left>" + ll;
  }
  xml += "</lower_left><pitch>" + pitch_str + "</pitch><universes>" +
         universes + "</universes></lattice>";

  auto doc = std::make_shared<pugi::xml_document>();
  doc->load_string(xml.c_str());
  auto lat = std::make_unique<RectLattice>(doc->child("lattice"));
  return lat;
}

//! Isotropic-like set of directions plus several degenerate ones
vector<Direction> test_directions()
{
  vector<Direction> dirs;
  for (int i = 1; i < 40; ++i) {
    double mu = -1.0 + 2.0 * i / 40.0;
    double phi = 2.0 * PI * i / 39.0;
    double sin_theta = std::sqrt(1.0 - mu * mu);
    dirs.push_back({sin_theta * std::cos(phi), sin_theta * std::sin(phi), mu});
  }
  // Directions parallel to the axes and to the tile diagonals
  double s = 1.0 / std::sqrt(2.0);
  for (Direction u : {Direction {1.0, 0.0, 0.0}, Direction {-1.0, 0.0, 0.0},
         Direction {0.0, 1.0, 0.0}, Direction {0.0, -1.0, 0.0},
         Direction {s, s, 0.0}, Direction {-s, s, 0.0}}) {
    dirs.push_back(u);
  }
  return dirs;
}

} // namespace

TEST_CASE("Rectangular lattice tile crossings are scale invariant")
{
  // The same lattice is examined over a wide range of lattice sizes. Nothing in
  // the crossing calculation may depend on the absolute size of the model.
  for (double pitch : {1.0e-4, 1.26, 100.0, 1.0e3, 1.0e6, 1.0e9}) {
    auto lat = make_lattice("3 3", -1.5 * pitch, pitch, 9);
    array<int, 3> i_xyz {1, 1, 0};

    for (const auto& u : test_directions()) {
      // Points inside the central tile, including its exact center
      for (double f : {0.0, 0.3, -0.45}) {
        Position r {f * pitch, -f * pitch, 0.0};
        auto [d, trans] = lat->distance(r, u, i_xyz);

        // A tile crossing must always be reported for a two-dimensional
        // lattice unless the particle moves parallel to the tile axes
        bool moves_in_plane = (u.x != 0.0) || (u.y != 0.0);
        REQUIRE(moves_in_plane == (d < INFTY));

        int n_changed = std::abs(trans[0]) + std::abs(trans[1]);
        REQUIRE(trans[2] == 0);
        if (!moves_in_plane) {
          // No crossing, hence no change of tile indices
          REQUIRE(n_changed == 0);
          continue;
        }

        // A finite distance always changes exactly one tile index, and the
        // index changes in the direction of motion
        REQUIRE(n_changed == 1);
        REQUIRE(d > 0.0);
        int axis = (trans[0] != 0) ? 0 : 1;
        REQUIRE(trans[axis] == (u[axis] > 0.0 ? 1 : -1));

        // The reported distance reaches the face of that axis and does not
        // overshoot the faces of the other axes
        Position r_hit = r + d * u;
        double face = std::copysign(0.5 * pitch, u[axis]);
        REQUIRE(std::abs(r_hit[axis] - face) <= 1.0e-10 * pitch);
        for (int i = 0; i < 2; ++i) {
          REQUIRE(std::abs(r_hit[i]) <= 0.5 * pitch * (1.0 + 1.0e-10));
        }
      }
    }
  }
}

TEST_CASE("Three-dimensional rectangular lattice tile crossings")
{
  for (double pitch : {1.26, 1.0e3, 1.0e6}) {
    auto lat = make_lattice("3 3 3", -1.5 * pitch, pitch, 27);
    array<int, 3> i_xyz {1, 1, 1};

    for (const auto& u : test_directions()) {
      Position r {0.1 * pitch, -0.2 * pitch, 0.35 * pitch};
      auto [d, trans] = lat->distance(r, u, i_xyz);

      REQUIRE(d < INFTY);
      REQUIRE(d > 0.0);
      REQUIRE(std::abs(trans[0]) + std::abs(trans[1]) + std::abs(trans[2]) == 1);

      int axis = (trans[0] != 0) ? 0 : ((trans[1] != 0) ? 1 : 2);
      REQUIRE(trans[axis] == (u[axis] > 0.0 ? 1 : -1));

      Position r_hit = r + d * u;
      double face = std::copysign(0.5 * pitch, u[axis]);
      REQUIRE(std::abs(r_hit[axis] - face) <= 1.0e-10 * pitch);
      for (int i = 0; i < 3; ++i) {
        REQUIRE(std::abs(r_hit[i]) <= 0.5 * pitch * (1.0 + 1.0e-10));
      }
    }
  }
}

TEST_CASE("Particle on a lattice tile face is not stuck on it")
{
  for (double pitch : {1.26, 1.0e3, 1.0e6}) {
    auto lat = make_lattice("3 3", -1.5 * pitch, pitch, 9);
    array<int, 3> i_xyz {1, 1, 0};

    // Sitting exactly on the oncoming face must not produce a zero distance,
    // which would prevent the particle from ever moving
    Direction u {1.0, 0.0, 0.0};
    Position r {0.5 * pitch, 0.0, 0.0};
    auto [d, trans] = lat->distance(r, u, i_xyz);
    REQUIRE(d > 0.0);

    // Sitting on the opposite face is an ordinary crossing of a full tile
    Position r_back {-0.5 * pitch, 0.0, 0.0};
    auto [d_back, trans_back] = lat->distance(r_back, u, i_xyz);
    REQUIRE(trans_back[0] == 1);
    REQUIRE(std::abs(d_back - pitch) <= 1.0e-10 * pitch);
  }
}
